198	/// Think Twice flashback: draw a card from graveyard, spell is exiled.
199	#[test]
200	fn think_twice_draws_from_graveyard() {
201	    let reg = registry();
202	    let mut state = game_at_step(Step::PrecombatMain, P0);
203	
204	    // Stock library so there's a card to draw.
205	    let mountain_id = reg.get_id_by_name("Mountain").unwrap();
206	    let lib_card = state.create_object(mountain_id, P0, Zone::Library, None, None);
207	    state.get_object_mut(lib_card).unwrap().name = "Mountain".into();
208	    state.get_player_mut(P0).library_order = vec![lib_card];
209	
210	    let hand_before = state.objects_in_zone(Zone::Hand, P0).len();
211	
212	    // Put Think Twice in graveyard. Flashback cost: {2}{U}.
213	    let tt_id = reg.get_id_by_name("Think Twice").unwrap();
214	    let tt = state.create_object(tt_id, P0, Zone::Graveyard, None, None);
215	    state.get_object_mut(tt).unwrap().name = "Think Twice".into();
216	    state.get_player_mut(P0).mana_pool.add(ManaType::Blue, 3);
217	
218	    state = cast_and_resolve(&state, &reg, tt, vec![]);
219	
220	    let hand_after = state.objects_in_zone(Zone::Hand, P0).len();
221	    assert_eq!(hand_after, hand_before + 1,
222	        "Think Twice should draw one card");
223	    assert_eq!(state.get_object(tt).unwrap().zone, Zone::Exile,
224	        "Think Twice cast via flashback should be exiled");
225	}
